command:
echo 'import re

def boot():
    def match_pattern(pattern_bytes, records, flags):
        pattern = pattern_bytes.decode("ascii")
        records = [record.decode("ascii") for record in records]
        if flags == "ASCII_IGNORE_CASE":
            pattern = re.compile(pattern, re.IGNORECASE)
        else:
            pattern = re.compile(pattern)
        selected = tuple(record.encode("ascii") for record in records if pattern.fullmatch(record))
        return selected

    return match_pattern
' > app/service.csirpy

